#include <math.h>
#include <stdio.h>
#include "convert.h"

double round1(double x)
{
    return round(x * 10.0) / 10.0;
}

double to_celsius(double value, char unit)
{
    switch (unit) {
    case 'C': return value;
    case 'F': return (value - 32.0) * 5.0 / 9.0;
    case 'K': return value - 273.15;
    default: return NAN;
    }
}

double celsius_to_fahrenheit(double c)
{
    return round1(c * 9.0 / 5.0 + 32.0);
}

double celsius_to_kelvin(double c)
{
    return round1(c + 273.15);
}

int main(void)
{
    double value = 0;
    char unit = 0;
    while (scanf("%lf %c", &value, &unit) == 2) {
        double c = to_celsius(value, unit);
        if (isnan(c)) {
            printf("Unknown unit: %c\n", unit);
            continue;
        }
        printf("%.1f C = %.1f F = %.1f K\n", round1(c) + 0.0, celsius_to_fahrenheit(c), celsius_to_kelvin(c));
    }
    return 0;
}

